{"filePath": "/Users/dwahl/Scripts/pantoken/docs/scripts/lib/og-fonts.ts", "content": "/**
 * Script fonts for the social-card renderer (`docs/scripts/gen-og.ts`).
 *
 * The card's brand face — Atkinson Hyperlegible Next — is vendored under `docs/assets/fonts`, but it
 * only covers Latin. Rendering a card for every locale needs a face per non-Latin script, and the
 * Noto family that covers them all is far too large to commit (~53 MB of variable TTFs). So they're
 * fetched once into a git-ignored cache under `docs/assets/fonts/noto/`, from a pinned `google/fonts`
 * commit, and each download is checked against a recorded SHA-256 before it's used. A cached file is
 * reused as-is, so only the first `docs:assets` run on a machine (or a cold CI runner) pays for it.
 *
 * `resvg` reads TTF/OTF, and `google/fonts` now ships Noto only as variable TTFs. `resvg` renders the
 * default instance of a variable font rather than instancing the `wght` axis, so non-Latin cards come
 * out at regular weight — acceptable for a social card, and the alternative (static instances) is no
 * longer published upstream.
 *
 * @module
 */
import { createHash } from "node:crypto";
import { mkdirSync, readFileSync, writeFileSync } from "node:fs";
import { fileURLToPath } from "node:url";

/** The `google/fonts` commit every font below is pinned to. */
const PIN = "205859f680703e449fe05dce0f792cc041d6dc89";

/** A downloadable script font: where to get it, what it's called, and what it must hash to. */
interface NotoFont {
  /** The path under `ofl/` in `google/fonts`, URL-encoded. */
  path: string;
  /** The `font-family` name to reference it by in the SVG. */
  family: string;
  /** SHA-256 of the file at {@link PIN}. */
  sha256: string;
  /** Ideographic scripts advance about one em per glyph and wrap without spaces. */
  cjk?: boolean;
}

const NOTO_FONTS = {
  sans: {
    path: "notosans/NotoSans%5Bwdth,wght%5D.ttf",
    family: "Noto Sans",
    sha256: "bfb7bb691513f12e734dc346c03a03f784912432d7e3fa8e56efcf906fe86b3d",
  },
  arabic: {
    path: "notosansarabic/NotoSansArabic%5Bwdth,wght%5D.ttf",
    family: "Noto Sans Arabic",
    sha256: "63111b5b2e074dd48cc67692e0a2726d86ee94c1c37fe8598257b7b4e87e869e",
  },
  hebrew: {
    path: "notosanshebrew/NotoSansHebrew%5Bwdth,wght%5D.ttf",
    family: "Noto Sans Hebrew",
    sha256: "7ef36a2c3593758cdb622e1bdef4f84523e92fbc3ccc667438dd80ff54c2de88",
  },
  devanagari: {
    path: "notosansdevanagari/NotoSansDevanagari%5Bwdth,wght%5D.ttf",
    family: "Noto Sans Devanagari",
    sha256: "9ce7b04f60e363d8870e5997744cf85cf69d38a4d7d129d364d92a3b14b461d7",
  },
  armenian: {
    path: "notosansarmenian/NotoSansArmenian%5Bwdth,wght%5D.ttf",
    family: "Noto Sans Armenian",
    sha256: "0870908d8318435a5daf1cd280ae15063f990cd9ad60f3e94c734ce9e1ffef71",
  },
  thai: {
    path: "notosansthai/NotoSansThai%5Bwdth,wght%5D.ttf",
    family: "Noto Sans Thai",
    sha256: "5a1c559bb539583c8a1fd99d1c5b9491e5e14478c9cd2bd0970d5c3096cc9ef8",
  },
  japanese: {
    path: "notosansjp/NotoSansJP%5Bwght%5D.ttf",
    family: "Noto Sans JP",
    sha256: "c2f3b4d463500a2ddcd3849cded1fceeb9fd6d1c32e6cbecd568453ba50fc68f",
    cjk: true,
  },
  korean: {
    path: "notosanskr/NotoSansKR%5Bwght%5D.ttf",
    family: "Noto Sans KR",
    sha256: "194018e6b2b293a7964f037b25c0249ce1418bc9ab3c971060a03aa57861e252",
    cjk: true,
  },
  simplifiedChinese: {
    path: "notosanssc/NotoSansSC%5Bwght%5D.ttf",
    family: "Noto Sans SC",
    sha256: "a3041811a78c361b1de50f953c805e0244951c21c5bd412f7232ef0d899af0da",
    cjk: true,
  },
  traditionalChinese: {
    path: "notosanstc/NotoSansTC%5Bwght%5D.ttf",
    family: "Noto Sans TC",
    sha256: "864727d210d54f2537bbe23b3a839436c3992af72de9322af5270897246bd44f",
    cjk: true,
  },
} as const satisfies Record<string, NotoFont>;

type NotoKey = keyof typeof NOTO_FONTS;

/**
 * The script font each locale's card needs. Locales absent from this map render in the vendored
 * Latin face alone; `el`, `ru`, and `uk` take Noto Sans for Greek and Cyrillic coverage.
 */
const LOCALE_FONTS: Record<string, NotoKey> = {
  ar: "arabic",
  fa: "arabic",
  he: "hebrew",
  hi: "devanagari",
  hy: "armenian",
  th: "thai",
  el: "sans",
  ru: "sans",
  uk: "sans",
  ja: "japanese",
  ko: "korean",
  "zh-Hans": "simplifiedChinese",
  "zh-Hant": "traditionalChinese",
};

const cacheDir = fileURLToPath(new URL("../../assets/fonts/noto/", import.meta.url));
const cachePath = (key: NotoKey): string => `${cacheDir}${key}.ttf`;

const sha256 = (bytes: Uint8Array): string =>
  createHash("sha256").update(bytes).digest("hex");

/** Read the cached file for `key`, or `undefined` if it's absent or doesn't match its pinned hash. */
function readCached(key: NotoKey): Uint8Array | undefined {
  try {
    const bytes = readFileSync(cachePath(key));
    return sha256(bytes) === NOTO_FONTS[key].sha256 ? bytes : undefined;
  } catch {
    return undefined;
  }
}

/**
 * Resolve a script font to a local file path, downloading and caching it on first use.
 *
 * @returns The path, or `undefined` when the font is neither cached nor reachable — the caller then
 *   falls back to the Latin card text rather than rendering a page of tofu.
 */
async function resolveFont(key: NotoKey): Promise<string | undefined> {
  if (readCached(key)) return cachePath(key);

  const url = `https://raw.githubusercontent.com/google/fonts/${PIN}/ofl/${NOTO_FONTS[key].path}`;
  let bytes: Uint8Array;
  try {
    const response = await fetch(url);
    if (!response.ok) throw new Error(`HTTP ${response.status}`);
    bytes = new Uint8Array(await response.arrayBuffer());
  } catch (error) {
    console.warn(`gen-og: could not fetch ${NOTO_FONTS[key].family} (${String(error)})`);
    return undefined;
  }

  const digest = sha256(bytes);
  if (digest !== NOTO_FONTS[key].sha256) {
    // A mismatch means the pinned URL served something other than the vetted file; never cache it.
    console.warn(
      `gen-og: ${NOTO_FONTS[key].family} failed its integrity check (got ${digest}) — skipping`,
    );
    return undefined;
  }

  mkdirSync(cacheDir, { recursive: true });
  writeFileSync(cachePath(key), bytes);
  return cachePath(key);
}

/** The font resources a locale's card renders with. */
export interface LocaleFonts {
  /** Every TTF `resvg` should load, the locale's script font first. */
  files: string[];
  /** The SVG `font-family` list for the card's text. */
  family: string;
  /** Whether the text wraps by character (ideographic) rather than by word. */
  cjk: boolean;
  /** Whether the locale's own script font resolved; `false` means fall back to the English text. */
  localized: boolean;
}

/**
 * Resolve the fonts for one locale's card.
 *
 * @param locale - The docs locale key (`root` for English).
 * @param latinFamily - The vendored brand family name.
 * @param latinFiles - The vendored brand face files.
 * @returns The {@link LocaleFonts} to render with.
 */
export async function localeFonts(
  locale: string,
  latinFamily: string,
  latinFiles: readonly string[],
): Promise<LocaleFonts> {
  const key = LOCALE_FONTS[locale];
  if (!key) {
    return { files: [...latinFiles], family: latinFamily, cjk: false, localized: true };
  }
  const file = await resolveFont(key);
  if (!file) {
    return { files: [...latinFiles], family: latinFamily, cjk: false, localized: false };
  }
  const font = NOTO_FONTS[key];
  return {
    files: [file, ...latinFiles],
    family: `${font.family}, ${latinFamily}`,
    cjk: "cjk" in font && font.cjk === true,
    localized: true,
  };
}
"}

{"content": "/**
 * Generate the social cards served at https://pantoken.app/og.png (and og-<locale>.png) — the image
 * link scrapers (Slack, iMessage, X, LinkedIn, Discord, Facebook) show when a pantoken docs URL
 * unfurls. Renders a 1200×630 PNG from an inline SVG that reuses the docs theme's home background (the
 * navy field with concentric blue circles bleeding off a corner, see
 * `.vitepress/theme/pantoken.css` → `--vp-home-bg-image`) and sets the pantoken wordmark over it.
 *
 * Every locale gets its own card. The wordmark comes from `@pantoken/plugin-logos`' vendored asset set
 * (`horizontal-reversed`, plus the purpose-drawn non-Latin variants), so a locale whose script has its
 * own wordmark gets that one instead of the Latin lockup. RTL locales (`ar`, `fa`, `he`) mirror the
 * whole card: the ring field moves to the bottom-left corner and the wordmark and text anchor right.
 *
 * The headline and supporting line are read straight from each locale's `docs/{locale}/index.md`
 * `hero.text`/`hero.tagline` frontmatter — the same "docs.home" strings the home page itself renders
 * (see `docs/scripts/check-locale-drift.ts`), so the card always matches what a visitor sees.
 *
 * Latin text renders in Atkinson Hyperlegible Next — the same face the docs theme uses
 * (`--vp-font-family-base`). The faces are bundled (converted to TTF from the vendored `.woff2` under
 * `formats/components/assets/fonts`, since resvg reads TTF/OTF, not WOFF2) and loaded explicitly with
 * `loadSystemFonts` OFF, so the card renders identically on CI's `ubuntu-latest`, which ships none of
 * the fonts a `loadSystemFonts` build would otherwise fall back to. Non-Latin scripts add a cached Noto
 * face on top of it — see `lib/og-fonts.ts`. If a script font can't be resolved, that locale's card
 * still gets written, with the English text, so no `og-<locale>.png` ever 404s.
 *
 * Regenerated on every build as part of `docs:assets`, so `docs/public/og*.png` are git-ignored, not
 * committed. Run `vp run docs:og` to refresh them on their own while iterating on the card design.
 *
 * @module
 */
import { readFileSync, writeFileSync } from "node:fs";
import { fileURLToPath } from "node:url";
import { Resvg } from "@resvg/resvg-js";
import {
  type DocsLocale,
  LOCALE_THEMES,
  NON_LATIN_LOCALES,
  NON_ROOT_LOCALES,
} from "../.vitepress/i18n.ts";
import { type LocaleFonts, localeFonts } from "./lib/og-fonts.ts";

const WIDTH = 1200;
const HEIGHT = 630;

// The bundled type family and its faces. resvg matches the SVG's `font-family` against the name in
// each loaded file, then picks the face by `font-weight`; the card uses 400/500/600/700.
const FONT = "Atkinson Hyperlegible Next";
const fontFile = (weight: string): string =>
  fileURLToPath(
    new URL(
      `../assets/fonts/AtkinsonHyperlegibleNext/AtkinsonHyperlegibleNext-${weight}.ttf`,
      import.meta.url,
    ),
  );
const FONT_FILES = ["Regular", "Medium", "SemiBold", "Bold"].map(fontFile);

// Palette lifted from the docs theme's home background SVG (pantoken.css `--vp-home-bg-image`)
const HEADER = "#7fb4f1";
const NAVY = "#002b4d"; // background field
const RING_1 = "#004880"; // outermost concentric ring
const RING_2 = "#0065b3";
const RING_3 = "#0090ff"; // brightest ring + brand-blue accent
const WHITE = "#ffffff";
const MUTED = "#aab0b5"; // desaturated blue for the supporting line
const URL_FILL = WHITE;

// The theme background anchors three concentric circles at a corner of a 374×160 field (radii
// 200/140/80). Scale those radii to the card width so the card reproduces the same look at 1200×630.
// The corner is bottom-right for LTR and bottom-left for RTL, opposite the text.
const scale = WIDTH / 374;
const ring = (r: number, fill: string, cx: number): string =>
  `<circle cx="${cx}" cy="${HEIGHT}" r="${Math.round(r * scale)}" fill="${fill}" />`;

// Text layout. Wordmark, headline, and tagline share a margin on the text side; the tagline wraps to
// fit, and the footer URL slides down to clear however many tagline lines that produced.
const MARGIN_X = 100;
const MAX_TEXT_WIDTH = WIDTH - MARGIN_X * 2 - 100; // leaves room clear of the ring corner
const LOGO_Y = 200;
const LOGO_HEIGHT = 99;
const HEADLINE_FONT_SIZE = 48;
const TAGLINE_FONT_SIZE = 29;
const TAGLINE_START_Y = 444;
const TAGLINE_LINE_HEIGHT = 29;
const TAGLINE_MAX_LINES = 3;
const FOOTER_GAP_AFTER_LAST_LINE = 83; // matches the original fixed 2-line layout (444+29+83=556)

const escapeXml = (text: string): string =>
  text.replace(/&/g, "&amp;").replace(/</g, "&lt;").replace(/>/g, "&gt;");

// No real text-metrics engine is available at generation time, so estimate glyph width as a fraction
// of the font size — tuned per weight (bold runs wider than medium), and one full em for ideographs —
// to decide wrap points and whether a line still overflows once wrapped.
const HEADLINE_ADVANCE = 0.62;
const TAGLINE_ADVANCE = 0.52;
const IDEOGRAPH_ADVANCE = 1;

const estimateWidth = (text: string, fontSize: number, avgCharWidth: number): number =>
  text.length * fontSize * avgCharWidth;

/**
 * Greedy-wrap `text` into lines no wider than `maxWidth` (estimated). Ideographic scripts write
 * without spaces, so they break between characters instead of between words.
 */
function wrapText(
  text: string,
  fontSize: number,
  avgCharWidth: number,
  maxWidth: number,
  cjk: boolean,
): string[] {
  const units = cjk ? [...text] : text.split(/\s+/).filter(Boolean);
  const join = cjk ? "" : " ";
  const lines: string[] = [];
  let current = "";
  for (const unit of units) {
    const candidate = current ? `${current}${join}${unit}` : unit;
    if (current && estimateWidth(candidate, fontSize, avgCharWidth) > maxWidth) {
      lines.push(current);
      current = unit;
    } else {
      current = candidate;
    }
  }
  if (current) lines.push(current);
  return lines;
}

/** Where a card's text and wordmark sit, and which way they run. */
interface Layout {
  rtl: boolean;
  /** The x the text anchors from — the left margin for LTR, the right margin for RTL. */
  anchorX: number;
  ringCx: number;
}

const layoutFor = (locale: DocsLocale): Layout => {
  const rtl = LOCALE_THEMES[locale].dir === "rtl";
  return { rtl, anchorX: rtl ? WIDTH - MARGIN_X : MARGIN_X, ringCx: rtl ? 0 : WIDTH };
};

/** Render `text` as an SVG `<text>`, compressing it with `textLength` if it still overflows `maxWidth`. */
function textLine(params: {
  text: string;
  y: number;
  fontSize: number;
  fontWeight: number;
  fill: string;
  avgCharWidth: number;
  maxWidth: number;
  fontFamily: string;
  layout: Layout;
}): string {
  const overflow =
    estimateWidth(params.text, params.fontSize, params.avgCharWidth) > params.maxWidth;
  const lengthAttrs = overflow
    ? ` textLength="${params.maxWidth}" lengthAdjust="spacingAndGlyphs"`
    : "";
  const directionAttrs = params.layout.rtl ? ` text-anchor="end" direction="rtl"` : "";
  return `<text x="${params.layout.anchorX}" y="${params.y}" font-family="${params.fontFamily}" font-size="${params.fontSize}" font-weight="${params.fontWeight}" fill="${params.fill}"${directionAttrs}${lengthAttrs}>${escapeXml(params.text)}</text>`;
}

/** Path to the vendored pantoken wordmark for a script, `undefined` meaning the Latin lockup. */
const wordmarkPath = (lang: string | undefined): string =>
  fileURLToPath(
    new URL(
      `../../plugins/pantoken/logos/assets/logos/pantoken/horizontal-reversed${lang ? `-${lang}` : ""}.svg`,
      import.meta.url,
    ),
  );

/**
 * Place a wordmark SVG on the card as a nested `<svg>`, scaled to {@link LOGO_HEIGHT} and anchored to
 * the text margin. Each localized wordmark has its own viewBox, so the aspect ratio is read from the
 * file rather than assumed.
 */
function wordmark(locale: DocsLocale, layout: Layout): string {
  const source = readFileSync(wordmarkPath(NON_LATIN_LOCALES[locale]), "utf8");
  const viewBox = source.match(/viewBox="([^"]+)"/)?.[1];
  if (!viewBox) throw new Error(`gen-og: ${wordmarkPath(NON_LATIN_LOCALES[locale])} has no viewBox`);
  const [, , boxWidth, boxHeight] = viewBox.split(/[\s,]+/).map(Number);

  const height = Math.min(LOGO_HEIGHT, (MAX_TEXT_WIDTH * boxHeight) / boxWidth);
  const width = (height * boxWidth) / boxHeight;
  const x = layout.rtl ? layout.anchorX - width : layout.anchorX;
  const inner = source.replace(/^[\s\S]*?<svg[^>]*>/, "").replace(/<\/svg>\s*$/, "");
  return `<svg x="${x}" y="${LOGO_Y + (LOGO_HEIGHT - height) / 2}" width="${width}" height="${height}" viewBox="${viewBox}">${inner}</svg>`;
}

/** Path to a locale's home page source, `root` being the undecorated top-level `index.md`. */
const heroIndexPath = (localeKey: DocsLocale): string =>
  fileURLToPath(
    new URL(localeKey === "root" ? "../index.md" : `../${localeKey}/index.md`, import.meta.url),
  );

function readHero(localeKey: DocsLocale): { headline: string; tagline: string } {
  const source = readFileSync(heroIndexPath(localeKey), "utf8");
  const frontmatter = source.split(/^---$/m)[1];
  if (!frontmatter) throw new Error(`gen-og: ${heroIndexPath(localeKey)} has no frontmatter`);
  const field = (key: string): string => {
    const match = frontmatter.match(new RegExp(`^ {2}${key}:\\s*(.+)$`, "m"));
    if (!match) throw new Error(`gen-og: ${heroIndexPath(localeKey)} is missing hero.${key}`);
    return match[1].trim();
  };
  return { headline: field("text"), tagline: field("tagline") };
}

function renderCard(
  locale: DocsLocale,
  hero: { headline: string; tagline: string },
  fonts: LocaleFonts,
): Buffer {
  const layout = layoutFor(locale);
  const headlineAdvance = fonts.cjk ? IDEOGRAPH_ADVANCE : HEADLINE_ADVANCE;
  const taglineAdvance = fonts.cjk ? IDEOGRAPH_ADVANCE : TAGLINE_ADVANCE;

  const taglineLines = wrapText(
    hero.tagline,
    TAGLINE_FONT_SIZE,
    taglineAdvance,
    MAX_TEXT_WIDTH,
    fonts.cjk,
  ).reduce<string[]>((lines, line, index, all) => {
    // Keep at most TAGLINE_MAX_LINES: fold any overflow words into the last line (which then gets
    // compressed to fit by `textLine`'s `textLength` fallback) rather than growing the card taller.
    if (index < TAGLINE_MAX_LINES - 1 || all.length <= TAGLINE_MAX_LINES) {
      lines.push(line);
    } else if (index === TAGLINE_MAX_LINES - 1) {
      lines.push(all.slice(TAGLINE_MAX_LINES - 1).join(fonts.cjk ? "" : " "));
    }
    return lines;
  }, []);
  const footerY =
    TAGLINE_START_Y + (taglineLines.length - 1) * TAGLINE_LINE_HEIGHT + FOOTER_GAP_AFTER_LAST_LINE;

  const svg = `<svg xmlns="http://www.w3.org/2000/svg" width="${WIDTH}" height="${HEIGHT}" viewBox="0 0 ${WIDTH} ${HEIGHT}">
  <rect width="${WIDTH}" height="${HEIGHT}" fill="${NAVY}" />
  ${ring(200, RING_1, layout.ringCx)}
  ${ring(140, RING_2, layout.ringCx)}
  ${ring(80, RING_3, layout.ringCx)}

  <!-- Brand-blue top accent rule. -->
  <rect x="0" y="0" width="${WIDTH}" height="10" fill="${RING_3}" />

  <!-- Wordmark. -->
  ${wordmark(locale, layout)}

  <!-- Headline (the home hero text). -->
  ${textLine({
    text: hero.headline,
    y: 388,
    fontSize: HEADLINE_FONT_SIZE,
    fontWeight: 700,
    fill: HEADER,
    avgCharWidth: headlineAdvance,
    maxWidth: MAX_TEXT_WIDTH,
    fontFamily: fonts.family,
    layout,
  })}

  <!-- Supporting line (the home hero tagline, word-wrapped). -->
  ${taglineLines
    .map((line, index) =>
      textLine({
        text: line,
        y: TAGLINE_START_Y + index * TAGLINE_LINE_HEIGHT,
        fontSize: TAGLINE_FONT_SIZE,
        fontWeight: 500,
        fill: MUTED,
        avgCharWidth: taglineAdvance,
        maxWidth: MAX_TEXT_WIDTH,
        fontFamily: fonts.family,
        layout,
      }),
    )
    .join("\n  ")}

  <!-- Footer URL. The address is Latin in every locale, so it keeps the brand face and LTR flow. -->
  <text x="${layout.anchorX}" y="${footerY}" font-family="${FONT}" font-size="24" font-weight="400" fill="${URL_FILL}"${layout.rtl ? ' text-anchor="end"' : ""}>pantoken.app</text>
</svg>`;

  return new Resvg(svg, {
    fitTo: { mode: "width", value: WIDTH },
    font: { loadSystemFonts: false, fontFiles: fonts.files, defaultFontFamily: FONT },
  })
    .render()
    .asPng();
}

// One card per locale. `root` writes the original `og.png` filename other assets already reference;
// every other locale writes `og-<locale>.png`.
const cardLocales: DocsLocale[] = ["root", ...NON_ROOT_LOCALES];

for (const locale of cardLocales) {
  const fonts = await localeFonts(locale, FONT, FONT_FILES);
  // Without the locale's script font its own text would render as tofu, so show the English text on
  // the localized card instead — the file still exists, so `og:image` never points at a 404.
