{"content": "import { readFileSync, readdirSync } from "node:fs";

const ttf = readFileSync(
  new URL("./assets/fonts/AtkinsonHyperlegibleNext/AtkinsonHyperlegibleNext-Regular.ttf", import.meta.url),
);

function cmapCodepoints(buf) {
  const numTables = buf.readUInt16BE(4);
  let cmapOffset = 0;
  for (let i = 0; i < numTables; i++) {
    const rec = 12 + i * 16;
    if (buf.toString("ascii", rec, rec + 4) === "cmap") cmapOffset = buf.readUInt32BE(rec + 8);
  }
  const n = buf.readUInt16BE(cmapOffset + 2);
  const covered = new Set();
  for (let i = 0; i < n; i++) {
    const rec = cmapOffset + 4 + i * 8;
    const sub = cmapOffset + buf.readUInt32BE(rec + 4);
    const format = buf.readUInt16BE(sub);
    if (format === 4) {
      const segX2 = buf.readUInt16BE(sub + 6);
      const endBase = sub + 14;
      const startBase = endBase + segX2 + 2;
      for (let s = 0; s < segX2 / 2; s++) {
        const end = buf.readUInt16BE(endBase + s * 2);
        const start = buf.readUInt16BE(startBase + s * 2);
        for (let c = start; c <= end && c !== 0xffff; c++) covered.add(c);
      }
    } else if (format === 12) {
      const groups = buf.readUInt32BE(sub + 12);
      for (let g = 0; g < groups; g++) {
        const base = sub + 16 + g * 12;
        const start = buf.readUInt32BE(base);
        const end = buf.readUInt32BE(base + 4);
        for (let c = start; c <= end; c++) covered.add(c);
      }
    }
  }
  return covered;
}

const covered = cmapCodepoints(ttf);
const locales = readdirSync(new URL("./", import.meta.url), { withFileTypes: true })
  .filter((e) => e.isDirectory())
  .map((e) => e.name);

const check = (label, file) => {
  let source;
  try {
    source = readFileSync(file, "utf8");
  } catch {
    return;
  }
  const fm = source.split(/^---$/m)[1];
  if (!fm) return;
  const text = ["text", "tagline"]
    .map((k) => fm.match(new RegExp(`^ {2}${k}:\\s*(.+)$`, "m"))?.[1] ?? "")
    .join(" ");
  const missing = [...new Set([...text].filter((ch) => !covered.has(ch.codePointAt(0))))];
  if (missing.length) console.log(label, "→", missing.join(" "));
